package com.travelbird.ai.controller;
import com.travelbird.ai.dto.request.*;import com.travelbird.ai.dto.response.*;import com.travelbird.ai.service.ActiveAiRecommendationService;import com.travelbird.auth.security.AuthenticatedUser;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class AiRecommendationController{private final ActiveAiRecommendationService service;public AiRecommendationController(ActiveAiRecommendationService s){service=s;}@PostMapping("/ai/trip-recommendations")public ResponseEntity<AiJobAcceptedResponse> request(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody AiRecommendationRequest r){return ResponseEntity.accepted().body(service.request(u.userId(),r));}@PostMapping("/trips/{tripId}/ai-route-recommendations")public ResponseEntity<AiJobAcceptedResponse> trip(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long tripId,@Valid @RequestBody AiRouteRecommendationRequest r){return ResponseEntity.accepted().body(service.requestTrip(u.userId(),tripId,r));}@GetMapping("/ai/trip-recommendations/{jobId}")public AiJobStatusResponse status(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long jobId){return service.status(u.userId(),jobId);}}
